CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE branches(id bigserial PRIMARY KEY, name varchar(120) NOT NULL, active boolean NOT NULL DEFAULT true);
INSERT INTO branches(name) VALUES ('شعبه مرکزی');
CREATE TABLE settings(id integer PRIMARY KEY CHECK(id=1), organization varchar(160) NOT NULL DEFAULT 'سالن زیبایی BsiCenter', plan varchar(16) NOT NULL DEFAULT 'ADVANCED' CHECK(plan IN ('BASIC','STANDARD','ADVANCED','SMART')), expires_on date, timezone varchar(60) NOT NULL DEFAULT 'Asia/Tehran', currency varchar(10) NOT NULL DEFAULT 'TOMAN' CHECK(currency='TOMAN'), point_unit numeric(16,0) NOT NULL DEFAULT 100000 CHECK(point_unit>0), risk_days int NOT NULL DEFAULT 90 CHECK(risk_days>0), loyal_visits int NOT NULL DEFAULT 5 CHECK(loyal_visits>0));
INSERT INTO settings(id) VALUES(1);
CREATE TABLE staff(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, name varchar(160) NOT NULL, mobile varchar(20) NOT NULL DEFAULT '', specialty varchar(160) NOT NULL DEFAULT '', commission_rate numeric(5,2) NOT NULL DEFAULT 30 CHECK(commission_rate BETWEEN 0 AND 100), work_start time NOT NULL DEFAULT '09:00', work_end time NOT NULL DEFAULT '21:00', work_days varchar(30) NOT NULL DEFAULT '1,2,3,4,6,7', active boolean NOT NULL DEFAULT true, CHECK(work_end>work_start));
CREATE TABLE app_users(id bigserial PRIMARY KEY, username varchar(80) UNIQUE NOT NULL, password_hash varchar(100) NOT NULL, name varchar(160) NOT NULL, role varchar(20) NOT NULL CHECK(role IN ('ADMIN','MANAGER','RECEPTION','STYLIST','MARKETING','FINANCE')), branch_id bigint NOT NULL REFERENCES branches, staff_id bigint REFERENCES staff, active boolean NOT NULL DEFAULT true, failed_attempts int NOT NULL DEFAULT 0, locked_until timestamptz, CHECK(role<>'STYLIST' OR staff_id IS NOT NULL));
CREATE TABLE auth_sessions(id uuid PRIMARY KEY, user_id bigint NOT NULL REFERENCES app_users, token_hash varchar(64) UNIQUE NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked boolean NOT NULL DEFAULT false);
CREATE INDEX ON auth_sessions(user_id);
CREATE TABLE customers(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, first_name varchar(100) NOT NULL, last_name varchar(100) NOT NULL, mobile varchar(20) NOT NULL, alternate_mobile varchar(20), birth_date date, gender varchar(20), marital_status varchar(30), education varchar(120), occupation varchar(120), address varchar(500), city varchar(100), acquisition_channel varchar(60) NOT NULL DEFAULT 'OTHER', referrer_id bigint REFERENCES customers, preferred_staff_id bigint REFERENCES staff, contact_channel varchar(30) NOT NULL DEFAULT 'SMS', marketing_consent boolean NOT NULL DEFAULT false, consent_at timestamptz, notes varchar(2000), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,mobile));
CREATE INDEX ON customers(branch_id,last_name);
CREATE TABLE customer_preferences(id bigserial PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers, category varchar(60) NOT NULL, value varchar(500) NOT NULL);
CREATE TABLE customer_occasions(id bigserial PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers, title varchar(120) NOT NULL, occasion_date date NOT NULL);
CREATE TABLE services(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, name varchar(160) NOT NULL, category varchar(80) NOT NULL DEFAULT 'عمومی', description varchar(500), price numeric(16,0) NOT NULL CHECK(price>=0), material_cost numeric(16,0) NOT NULL DEFAULT 0 CHECK(material_cost>=0), duration_minutes int NOT NULL CHECK(duration_minutes BETWEEN 5 AND 480), buffer_minutes int NOT NULL DEFAULT 0 CHECK(buffer_minutes BETWEEN 0 AND 120), active boolean NOT NULL DEFAULT true);
CREATE TABLE staff_services(staff_id bigint NOT NULL REFERENCES staff, service_id bigint NOT NULL REFERENCES services, PRIMARY KEY(staff_id,service_id));
CREATE TABLE staff_leave(id bigserial PRIMARY KEY, staff_id bigint NOT NULL REFERENCES staff, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, reason varchar(300), CHECK(ends_at>starts_at));
CREATE TABLE products(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, name varchar(160) NOT NULL, category varchar(80) NOT NULL DEFAULT 'محصول', price numeric(16,0) NOT NULL CHECK(price>=0), cost numeric(16,0) NOT NULL DEFAULT 0 CHECK(cost>=0), stock int NOT NULL DEFAULT 0 CHECK(stock>=0), minimum_stock int NOT NULL DEFAULT 3 CHECK(minimum_stock>=0), supplier varchar(160), active boolean NOT NULL DEFAULT true);
CREATE TABLE stock_movements(id bigserial PRIMARY KEY, product_id bigint NOT NULL REFERENCES products, quantity int NOT NULL CHECK(quantity<>0), reason varchar(300) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE appointments(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, customer_id bigint NOT NULL REFERENCES customers, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status varchar(20) NOT NULL DEFAULT 'BOOKED' CHECK(status IN ('BOOKED','CONFIRMED','ARRIVED','COMPLETED','CANCELLED','NO_SHOW')), source varchar(30) NOT NULL DEFAULT 'RECEPTION', notes varchar(1000), cancel_reason varchar(500), created_by bigint NOT NULL REFERENCES app_users, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE INDEX ON appointments(branch_id,starts_at);
CREATE TABLE appointment_items(id bigserial PRIMARY KEY, appointment_id bigint NOT NULL REFERENCES appointments, service_id bigint NOT NULL REFERENCES services, staff_id bigint NOT NULL REFERENCES staff, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, blocked_until timestamptz NOT NULL, active boolean NOT NULL DEFAULT true, CHECK(ends_at>starts_at), CHECK(blocked_until>=ends_at), EXCLUDE USING gist(staff_id WITH =, tstzrange(starts_at,blocked_until,'[)') WITH &&) WHERE(active));
CREATE TABLE visits(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, customer_id bigint NOT NULL REFERENCES customers, appointment_id bigint UNIQUE REFERENCES appointments, status varchar(20) NOT NULL DEFAULT 'WAITING' CHECK(status IN ('WAITING','IN_SERVICE','COMPLETED','CANCELLED')), priority varchar(10) NOT NULL DEFAULT 'NORMAL' CHECK(priority IN ('NORMAL','VIP')), check_in_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, notes varchar(1000));
CREATE TABLE visit_services(id bigserial PRIMARY KEY, visit_id bigint NOT NULL REFERENCES visits, service_id bigint NOT NULL REFERENCES services, staff_id bigint NOT NULL REFERENCES staff, started_at timestamptz, completed_at timestamptz, status varchar(20) NOT NULL DEFAULT 'PLANNED' CHECK(status IN ('PLANNED','IN_SERVICE','COMPLETED','CANCELLED')), rating int CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE invoices(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, customer_id bigint NOT NULL REFERENCES customers, visit_id bigint UNIQUE REFERENCES visits, total numeric(16,0) NOT NULL CHECK(total>=0), discount numeric(16,0) NOT NULL DEFAULT 0 CHECK(discount>=0), tax numeric(16,0) NOT NULL DEFAULT 0 CHECK(tax>=0), status varchar(20) NOT NULL DEFAULT 'ISSUED' CHECK(status IN ('ISSUED','PARTIAL','PAID','VOID')), created_by bigint NOT NULL REFERENCES app_users, created_at timestamptz NOT NULL DEFAULT now(), void_reason varchar(500));
CREATE TABLE invoice_items(id bigserial PRIMARY KEY, invoice_id bigint NOT NULL REFERENCES invoices, service_id bigint REFERENCES services, product_id bigint REFERENCES products, staff_id bigint REFERENCES staff, description varchar(200) NOT NULL, quantity int NOT NULL CHECK(quantity BETWEEN 1 AND 1000), unit_price numeric(16,0) NOT NULL CHECK(unit_price>=0), unit_cost numeric(16,0) NOT NULL CHECK(unit_cost>=0), discount numeric(16,0) NOT NULL CHECK(discount>=0), total numeric(16,0) NOT NULL CHECK(total>=0), commission_rate numeric(5,2) NOT NULL DEFAULT 0, CHECK((service_id IS NULL)<>(product_id IS NULL)));
CREATE TABLE accounts(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, name varchar(120) NOT NULL, active boolean NOT NULL DEFAULT true);
INSERT INTO accounts(branch_id,name) VALUES(1,'صندوق اصلی'),(1,'حساب کارتخوان');
CREATE TABLE payments(id bigserial PRIMARY KEY, invoice_id bigint NOT NULL REFERENCES invoices, amount numeric(16,0) NOT NULL CHECK(amount>0), method varchar(20) NOT NULL CHECK(method IN ('CASH','CARD','TRANSFER')), account_id bigint NOT NULL REFERENCES accounts, tracking_code varchar(100), idempotency_key uuid UNIQUE NOT NULL, created_by bigint NOT NULL REFERENCES app_users, created_at timestamptz NOT NULL DEFAULT now(), reversed boolean NOT NULL DEFAULT false, reversal_reason varchar(500));
CREATE TABLE expenses(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, account_id bigint NOT NULL REFERENCES accounts, title varchar(160) NOT NULL, category varchar(80) NOT NULL, amount numeric(16,0) NOT NULL CHECK(amount>0), created_by bigint NOT NULL REFERENCES app_users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE financial_entries(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, account_id bigint NOT NULL REFERENCES accounts, amount numeric(16,0) NOT NULL, kind varchar(30) NOT NULL, payment_id bigint REFERENCES payments, expense_id bigint REFERENCES expenses, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commissions(id bigserial PRIMARY KEY, invoice_item_id bigint UNIQUE NOT NULL REFERENCES invoice_items, staff_id bigint NOT NULL REFERENCES staff, basis numeric(16,0) NOT NULL, rate numeric(5,2) NOT NULL, amount numeric(16,0) NOT NULL, status varchar(20) NOT NULL DEFAULT 'CALCULATED' CHECK(status IN ('CALCULATED','APPROVED','SETTLED','VOID')), settled_at timestamptz);
CREATE TABLE loyalty_entries(id bigserial PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers, invoice_id bigint REFERENCES invoices, points int NOT NULL, reason varchar(300) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX ON loyalty_entries(invoice_id) WHERE invoice_id IS NOT NULL;
CREATE TABLE rfm_snapshots(id bigserial PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers, calculated_on date NOT NULL, recency int, frequency int NOT NULL, monetary numeric(16,0) NOT NULL, segment varchar(20) NOT NULL, UNIQUE(customer_id,calculated_on));
CREATE TABLE campaigns(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, name varchar(160) NOT NULL, objective varchar(300), segment varchar(20) NOT NULL CHECK(segment IN ('ALL','LOYAL','GROWING','NEW','AT_RISK')), body varchar(1000) NOT NULL, budget numeric(16,0) NOT NULL DEFAULT 0 CHECK(budget>=0), status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','QUEUED','COMPLETED','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, customer_id bigint NOT NULL REFERENCES customers, campaign_id bigint REFERENCES campaigns, kind varchar(20) NOT NULL DEFAULT 'MARKETING', body varchar(1000) NOT NULL, status varchar(20) NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','SENDING','SENT','FAILED','CANCELLED')), provider_id varchar(120), error varchar(300), created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE campaign_recipients(campaign_id bigint NOT NULL REFERENCES campaigns, customer_id bigint NOT NULL REFERENCES customers, message_id bigint REFERENCES messages, PRIMARY KEY(campaign_id,customer_id));
CREATE TABLE events(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, name varchar(160) NOT NULL, description varchar(1000), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, venue varchar(250) NOT NULL, capacity int NOT NULL CHECK(capacity>0), budget numeric(16,0) NOT NULL DEFAULT 0 CHECK(budget>=0), status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','COMPLETED','CANCELLED')), CHECK(ends_at>starts_at));
CREATE TABLE event_participants(event_id bigint NOT NULL REFERENCES events, customer_id bigint NOT NULL REFERENCES customers, status varchar(20) NOT NULL DEFAULT 'REGISTERED' CHECK(status IN ('REGISTERED','ATTENDED','CANCELLED')), PRIMARY KEY(event_id,customer_id));
CREATE TABLE audit_logs(id bigserial PRIMARY KEY, branch_id bigint NOT NULL REFERENCES branches, user_id bigint REFERENCES app_users, action varchar(40) NOT NULL, entity varchar(50) NOT NULL, entity_id bigint, detail varchar(500), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoice_links(id bigserial PRIMARY KEY, invoice_id bigint NOT NULL REFERENCES invoices, token_hash varchar(64) UNIQUE NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
